"""Sales Trend Analyzer: weekly totals, week-over-week change, simple stats."""
import csv, statistics, sys

def weekly_totals(rows):
    totals = {}
    for r in rows:
        totals[r["week"]] = totals.get(r["week"], 0.0) + float(r["amount"])
    return dict(sorted(totals.items()))

def wow_change(totals):
    vals = list(totals.values())
    return [(b - a) / a * 100 for a, b in zip(vals, vals[1:]) if a]

if __name__ == "__main__":
    with open(sys.argv[1]) as f:
        t = weekly_totals(csv.DictReader(f))
    for k, v in t.items():
        print(f"{k}: ${v:,.2f}")
    ch = wow_change(t)
    if ch:
        print(f"mean WoW change: {statistics.mean(ch):.1f}%  stdev: {statistics.pstdev(ch):.1f}%")
EOF
